# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping entry write delay hook" do
  # "slow writes with a test hook and see the latency alert."
  # A hook production could switch on would let a setting slow every real write.
  it "never sets the slow write hook in the production environment" do
    production_config = Rails.root.join("config/environments/production.rb").read
    test_config = Rails.root.join("config/environments/test.rb").read

    expect(production_config).not_to include("entry_write_checkpoint")
    expect(production_config).not_to include("TIMEKEEPING_TEST_WRITE_DELAY_MS")
    expect(test_config).to include("entry_write_checkpoint")
  end
end

RSpec.describe "Timekeeping entry write delay hook on the create route" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  let(:delay_hook_company) { timekeeping_arrange.company }
  let(:delay_hook_project) { timekeeping_arrange.project(company: delay_hook_company) }
  let(:delay_hook_token) { timekeeping_arrange.token_for(timekeeping_arrange.user(company: delay_hook_company, role: "owner")) }

  around do |example|
    before_checkpoint = Rails.configuration.x.entry_write_checkpoint
    example.run
  ensure
    Rails.configuration.x.entry_write_checkpoint = before_checkpoint
  end

  def send_delay_hook_create
    body = { "project_id" => delay_hook_project, "work_date" => "2026-03-02", "duration" => 45.0, "note" => "Review",
             "source" => "manual", "source_metadata" => {} }
    post "/v1/companies/#{delay_hook_company}/entries",
         params: JSON.generate(body),
         headers: { "Content-Type" => "application/json", "Authorization" => "Bearer #{delay_hook_token}",
                    "Ownership-Generation" => timekeeping_arrange.current_generation.to_s,
                    "Idempotency-Key" => SecureRandom.uuid }
    response
  end

  it "records a real latency above the delay when the checkpoint sleeps, with no clock stub" do
    steps = []
    Rails.configuration.x.entry_write_checkpoint = lambda do |step|
      steps << step
      sleep(0.35) if step == :entry_written
    end

    expect(send_delay_hook_create.status).to eq(201)

    row = WriteMetricWindow.find_by!(company_id: delay_hook_company)
    expect(steps).to include(:entry_written)
    expect(row.latency_ms_sum).to be > 350
    expect(row.latency_ms_buckets.keys).to eq(["500"])
  end

  it "uses the writer's default checkpoint when the hook is unset" do
    Rails.configuration.x.entry_write_checkpoint = nil
    allow(Timekeeping::EntryWriter).to receive(:new).and_call_original

    expect(send_delay_hook_create.status).to eq(201)
    expect(Timekeeping::EntryWriter).to have_received(:new).with(no_args)
  end
end
